CREATE OR REPLACE FUNCTION public.post_team_comment(_topic uuid,_parent uuid,_body text,_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tm uuid; result_id uuid; c comments; BEGIN SELECT t.team_id INTO tm FROM discussion_topics t WHERE t.id=_topic; IF NOT team_channel_access(tm) OR _request IS NULL THEN RAISE EXCEPTION 'not_allowed'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()||':'||_request,0)); SELECT * INTO c FROM comments WHERE author_id=auth.uid() AND client_request_id=_request; IF FOUND THEN IF c.topic_id IS DISTINCT FROM _topic OR c.parent_id IS DISTINCT FROM _parent OR c.body IS DISTINCT FROM trim(_body) THEN RAISE EXCEPTION 'invalid_retry'; END IF; RETURN c.id; END IF; result_id:=post_comment(NULL,_topic,_parent,_body,NULL); UPDATE comments SET client_request_id=_request WHERE comments.id=result_id; RETURN result_id; END $$;
CREATE OR REPLACE FUNCTION public.create_team_announcement(_team uuid,_title text,_body text,_link text,_pinned boolean) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT save_team_announcement(_team,NULL,_title,_body,_link,_pinned,false); $$;
REVOKE ALL ON FUNCTION public.create_team_announcement(uuid,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_team_announcement(uuid,text,text,text,boolean) TO authenticated;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='announcements') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.announcements; END IF; IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='team_members') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.team_members; END IF; END $$;